import type { PartProgress, ProgressCounts, SkillAreaProgress, ToeicProgress } from "@/lib/progress/types";
import type { DiagnosisLabel, DiagnosisSignal, EvidenceState, SectionDiagnosis, ToeicDiagnosis } from "./types";

export const DIAGNOSIS_SAMPLE_THRESHOLDS = { early: 3, supported: 8 } as const;
export const DIAGNOSIS_ACCURACY_THRESHOLDS = { developing: 60, stable: 75, strong: 90 } as const;
export function evidenceState(attemptedCount: number): EvidenceState { if (attemptedCount < 3) return "INSUFFICIENT_DATA"; if (attemptedCount < 8) return "EARLY_SIGNAL"; return "SUPPORTED"; }
export function diagnosisLabel(attemptedCount: number, accuracy: number | null): DiagnosisLabel | null { const evidence = evidenceState(attemptedCount); if (evidence === "INSUFFICIENT_DATA" || accuracy === null) return null; if (evidence === "EARLY_SIGNAL") return "DEVELOPING"; if (accuracy < 60) return "NEEDS_ATTENTION"; if (accuracy < 75) return "DEVELOPING"; if (accuracy < 90) return "STABLE"; return "STRONG"; }
function priority(attemptedCount: number, accuracy: number | null): number | null { if (!attemptedCount || accuracy === null) return null; const state = evidenceState(attemptedCount); const weight = state === "SUPPORTED" ? 3 : state === "EARLY_SIGNAL" ? 1 : 0; return weight ? weight * 10_000 + (100 - accuracy) * 100 + Math.min(attemptedCount, 99) : null; }
function signal(counts: ProgressCounts, identity: Omit<DiagnosisSignal, keyof ProgressCounts | "evidence" | "label" | "priorityScore">): DiagnosisSignal { return { ...identity, ...counts, evidence: evidenceState(counts.attemptedCount), label: diagnosisLabel(counts.attemptedCount, counts.accuracy), priorityScore: priority(counts.attemptedCount, counts.accuracy) }; }
function section(area: SkillAreaProgress): SectionDiagnosis { const base = { skillArea: area.skillArea } as const; const parts = area.parts.map((part) => signal(part, { ...base, level: "PART", part: part.part, skill: null, subskill: null })); const skills: DiagnosisSignal[] = []; const subskills: DiagnosisSignal[] = []; for (const part of area.parts as PartProgress[]) for (const skill of part.skills) { skills.push(signal(skill, { ...base, level: "SKILL", part: part.part, skill: skill.name, subskill: null })); for (const subskill of skill.subskills) subskills.push(signal(subskill, { ...base, level: "SUBSKILL", part: part.part, skill: skill.name, subskill: subskill.name })); } return { skillArea: area.skillArea, overall: signal(area, { ...base, level: "SECTION", part: null, skill: null, subskill: null }), parts, skills, subskills }; }
export function rankDiagnosisSignals(signals: DiagnosisSignal[]): DiagnosisSignal[] { return signals.filter((item) => item.attemptedCount > 0 && item.priorityScore !== null).sort((a, b) => (b.priorityScore! - a.priorityScore!) || a.skillArea.localeCompare(b.skillArea) || ((a.part ?? 0) - (b.part ?? 0)) || (a.skill ?? "").localeCompare(b.skill ?? "") || (a.subskill ?? "").localeCompare(b.subskill ?? "")); }
export function calculateToeicDiagnosis(progress: ToeicProgress): ToeicDiagnosis { const listening = section(progress.listening); const reading = section(progress.reading); const detailed = [...listening.subskills, ...reading.subskills, ...listening.skills, ...reading.skills, ...listening.parts, ...reading.parts]; return { listening, reading, rankedImprovementAreas: rankDiagnosisSignals(detailed) }; }
